import{d as s,C as a,o as h,c as g,E as t,a3 as n}from"./chunks/framework.D4-ViStF.js";const x=JSON.parse('{"title":"咸卦","description":"第三十一卦·泽山咸——山上有泽，君子以虚受人。","frontmatter":{"title":"咸卦","description":"第三十一卦·泽山咸——山上有泽，君子以虚受人。","category":"hexagram","aliases":["咸","泽山咸"],"source":["《周易》"]},"headers":[],"relativePath":"yijing/hexagrams/hexagram-31.md","filePath":"yijing/hexagrams/hexagram-31.md","lastUpdated":1787730063000}'),m={name:"yijing/hexagrams/hexagram-31.md"},q=s({...m,setup(p){const r=[{id:"xianqimu",term:"咸其拇",pinyin:"xián qí mǔ",meaning:"感应到脚趾。拇，足趾。最初的触动，尚未被意念加工。"},{id:"xianqifei",term:"咸其腓",pinyin:"xián qí féi",meaning:"感应到小腿肚。腓，小腿肚。被感带动，切忌抢先妄动。"},{id:"xianqigu",term:"咸其股",pinyin:"xián qí gǔ",meaning:"感应到大腿。股，大腿。主控感出现，执著于「我要跟随感应」。"},{id:"zhiqisui",term:"执其随",pinyin:"zhí qí suí",meaning:"执著于跟随这件事。从自然感应，滑向「我要感应」。"},{id:"chongchong",term:"憧憧往来",pinyin:"chōng chōng wǎng lái",meaning:"心念来去不定。念头不断出入，连「我要不想了」也成为一个念。"},{id:"pengcong",term:"朋从尔思",pinyin:"péng cóng ěr sī",meaning:"内心长久系于什么，相关的人、事、念头便会随之聚集、响应。"},{id:"xianqimei",term:"咸其脢",pinyin:"xián qí méi",meaning:"感应到脊背。脢，背脊肉。内守、有根、有感而不被牵走。"},{id:"xianqifu",term:"咸其辅颊舌",pinyin:"xián qí fǔ jiá shé",meaning:"感应到辅、颊、舌。辅颊为面部外显，舌为内在出口——感应化为表情、语言、书写。"},{id:"zhizaiwai",term:"志在外",pinyin:"zhì zài wài",meaning:"志向在外。最初的触动，尚未形成可判断的方向。"},{id:"shunbuhai",term:"顺不害",pinyin:"shùn bù hài",meaning:"顺而不害。安守其位，让行动自然成熟，而不是由焦虑催促。"},{id:"zhizaisuiren",term:"志在随人",pinyin:"zhì zài suí rén",meaning:"志向在随人。执著于跟随，所执已经落了下乘。"},{id:"weiganhai",term:"未感害",pinyin:"wèi gǎn hài",meaning:"没有感应之害。贞吉悔亡，因为守正不被感应所害。"},{id:"weiguangda",term:"未光大",pinyin:"wèi guāng dà",meaning:"尚未光大。憧憧往来，心念纷纭则尚未光大。"},{id:"zhimo",term:"志末",pinyin:"zhì mò",meaning:"志向在末。守在脊背，不是追逐感受的末端，而是回到支撑自己的根。"},{id:"tengkoushuo",term:"滕口说",pinyin:"téng kǒu shuō",meaning:"张口空说。若只停在口舌，便是空说；表达之后，还要能回到本质。"}],e=[{position:"初六",type:"yin",text:"咸其拇。",xiang:"咸其拇，志在外也。",textModern:"感应从脚趾开始——脚趾与地相接，人不是先用概念接触世界，而是先以身体接触世界。感应本来一直都在，修习不是制造感应，是重新注意到它。",xiangModern:"感应到脚趾，志向在外——最初的触动，尚未形成可判断的方向。"},{position:"六二",type:"yin",text:"咸其腓，凶，居吉。",xiang:"虽凶居吉，顺不害也。",textModern:"脚趾一动，小腿会自然被带动；但若强迫小腿抢先发力，就打乱了自然次序。动则凶，居则吉——先居住在感受里，不急着把感受变成动作。",xiangModern:"虽凶居吉，顺而不害——安守其位，让行动自然成熟，而不是由焦虑催促。"},{position:"九三",type:"yang",text:"咸其股，执其随，往吝。",xiang:"咸其股，亦不处也。志在随人，所执下也。",textModern:"感应到大腿，「小我」开始出现——「我在掌控方向」。「执其随」不是单纯跟随，是执著于跟随这件事：从自然感应，滑向「我要感应」。",xiangModern:"咸其股，亦不处也，志在随人——执著于跟随，所执已经落了下乘。"},{position:"九四",type:"yang",text:"贞吉，悔亡。憧憧往来，朋从尔思。",xiang:"贞吉悔亡，未感害也。憧憧往来，未光大也。",textModern:"心是感应的中心，也是念头的市场。「憧憧往来」是念头不断出入；「朋从尔思」是你长期安住什么念，相关人事便向那个方向聚集。但关键不在「乱」，在开头四字「贞吉悔亡」——在乱中守正，乱才会成为通向安定的过程。",xiangModern:"贞吉悔亡，未感害也；憧憧往来，未光大也——守正则不被感应所害，心念往来则尚未光大。"},{position:"九五",type:"yang",text:"咸其脢，无悔。",xiang:"咸其脢，志末也。",textModern:"感应到脊背——脊背不负责展示、不负责言说，却默默支撑整个身体。九五的重点不是更多感受，是内守：有感，但不被感带走。",xiangModern:"咸其脢，志末也——守在脊背，不是追逐感受的末端，而是回到支撑自己的根。"},{position:"上六",type:"yin",text:"咸其辅颊舌。",xiang:"咸其辅颊舌，滕口说也。",textModern:"感应走完全身后，终于找到出口，化为表情、语言、书写与行动。关键不是说多说少，是如实、合时、不夸张、不借表达操控。感受了，如实表达；不压抑、不表演、不夸大、也不伤人。",xiangModern:"咸其辅颊舌，滕口说也——若只停在口舌，便是张口空说；表达之后，还要能回到本质。"}];return(u,i)=>{const o=a("DaoHexagramViewer"),l=a("DaoHexagramYaoCards"),d=a("DaoKeywordCards");return h(),g("div",null,[t(o,{name:"咸",fullName:"泽山咸",upper:"☱",lower:"☶",guaCi:"咸，亨，利贞。取女吉。",pinyin:["xián"],element:"金",direction:"西",insight:"泽在山上，虚而能受；感是入口，贞是边界。",guaSlug:"31zeshanxian",lines:e}),i[0]||(i[0]=n('<h2 id="象传" tabindex="-1">象传 <a class="header-anchor" href="#象传" aria-label="Permalink to &quot;象传&quot;">​</a></h2><p>山上有泽，咸。君子以虚受人。</p><p>上兑为泽、下艮为山，泽停聚在山的凹处，山不动、泽能润泽——山给了泽空间与安顿之处，泽赋予山气息、生机与流动。君子由此悟到：要<strong>以虚受人</strong>——心中留有空间，能容纳他人的处境、情绪、意见与存在。</p><p>「虚」不是空洞、不是没有立场，而是不让成见把内心塞满，不让「别人必须懂我」成为关系的前提；有边界，但不封闭。</p><h2 id="彖传" tabindex="-1">彖传 <a class="header-anchor" href="#彖传" aria-label="Permalink to &quot;彖传&quot;">​</a></h2><p>咸，感也。柔上而刚下，二气感应以相与。止而说，男下女，是以亨利贞，取女吉也。天地感而万物化生，圣人感人心而天下和平。观其所感，而天地万物之情可见矣。</p><p>逐句释义：</p><ul><li><strong>咸，感也</strong> —— 咸就是感。把「咸」理解为尚未被过度意志化、计算化的感通。</li><li><strong>柔上而刚下，二气感应以相与</strong> —— 柔者在上、刚者在下，阴阳二气交感而相互给予。</li><li><strong>止而说，男下女</strong> —— 艮为止（能止），兑为悦（能悦）；男下女，刚者放低、靠近、容纳。</li><li><strong>天地感而万物化生，圣人感人心而天下和平</strong> —— 天地交感而万物化生，圣人感通人心而天下和平。</li><li><strong>观其所感，而天地万物之情可见矣</strong> —— 看万物如何相感，天地万物的情实就显现了。</li></ul><blockquote><p><strong>无心之感</strong>：咸不是没有心，是不以私心强作感应——不预设别人必须怎样回应，不把情绪强塞给别人，不把「我要感应」变成新的执著。有感，但不急于占有、证明、操控。</p></blockquote><h2 id="六爻" tabindex="-1">六爻 <a class="header-anchor" href="#六爻" aria-label="Permalink to &quot;六爻&quot;">​</a></h2>',10)),t(l,{element:"金",guaSlug:"31zeshanxian",glossary:r,items:e}),i[1]||(i[1]=n('<h2 id="六爻详解" tabindex="-1">六爻详解 <a class="header-anchor" href="#六爻详解" aria-label="Permalink to &quot;六爻详解&quot;">​</a></h2><p>咸卦六爻以身体部位写感应的推进——从脚趾一路向上，到心，再到口舌：</p><h3 id="初六-·-咸其拇" tabindex="-1">初六 · 咸其拇 <a class="header-anchor" href="#初六-·-咸其拇" aria-label="Permalink to &quot;初六 · 咸其拇&quot;">​</a></h3><ul><li>「拇」是足趾，脚趾与地相接</li><li>站桩、走路、立定时，脚趾最先感知地面；人不是先用概念接触世界，是先以身体接触世界</li><li>感应本来一直都在，修习不是制造感应，是重新注意到它</li></ul><blockquote><p>感应从脚趾开始——起心动念之前，到起心动念初起之间的那一瞬。</p></blockquote><h3 id="六二-·-咸其腓-凶-居吉" tabindex="-1">六二 · 咸其腓，凶，居吉 <a class="header-anchor" href="#六二-·-咸其腓-凶-居吉" aria-label="Permalink to &quot;六二 · 咸其腓，凶，居吉&quot;">​</a></h3><ul><li>「腓」是小腿肚</li><li>脚趾一动，小腿会自然被带动；但强迫小腿抢先发力，就打乱了自然次序</li><li>动，凶；居，吉——「居」不是消极不动，是安守其位</li><li>现实：刚被触动就急于表态、刚有情绪就急于发泄、刚有灵感就急于证明</li></ul><blockquote><p>先居住在感受里，不急着把感受变成动作。</p></blockquote><h3 id="九三-·-咸其股-执其随-往吝" tabindex="-1">九三 · 咸其股，执其随，往吝 <a class="header-anchor" href="#九三-·-咸其股-执其随-往吝" aria-label="Permalink to &quot;九三 · 咸其股，执其随，往吝&quot;">​</a></h3><ul><li>「股」为大腿，行动、支撑和发力的部位</li><li>小我开始出现：「我在掌控方向，我在决定一切」</li><li>「执其随」不是单纯跟随，是执著于跟随这件事——从自然感应，滑向「我要感应」</li><li>解药不是反智，是：学到之后，仍能放下「我要靠此成为谁」的抓取</li></ul><blockquote><p>一边学习，一边损掉对学习的执。</p></blockquote><h3 id="九四-·-贞吉-悔亡。憧憧往来-朋从尔思" tabindex="-1">九四 · 贞吉，悔亡。憧憧往来，朋从尔思 <a class="header-anchor" href="#九四-·-贞吉-悔亡。憧憧往来-朋从尔思" aria-label="Permalink to &quot;九四 · 贞吉，悔亡。憧憧往来，朋从尔思&quot;">​</a></h3><ul><li>九四到了「心」，心会使感应变得复杂</li><li>「憧憧往来」：念头不断出入——想学习、想获利、想丢掉、想证明……连「我要不想了」也成为一个念</li><li>「朋从尔思」：你长期安住什么念，外部的人事、信息、行动与回馈，便向那个方向聚集</li><li>关键不在「乱」，在「贞吉悔亡」——守正，乱才成为通向安定的过程</li></ul><blockquote><p>念头还在，但不再由它们接管方向。</p></blockquote><h3 id="九五-·-咸其脢-无悔" tabindex="-1">九五 · 咸其脢，无悔 <a class="header-anchor" href="#九五-·-咸其脢-无悔" aria-label="Permalink to &quot;九五 · 咸其脢，无悔&quot;">​</a></h3><ul><li>「脢」指背部、脊背一带</li><li>脊背不在最前、不负责展示、不负责言说，却默默支撑整个身体</li><li>内守：有感，但不被感带走</li><li>刷手机仍会被带走，但已能意识到、能关掉回到书本——脊梁在生长</li></ul><blockquote><p>我有感受，我有念头，我也会摇摆；但我不再完全背弃自己。</p></blockquote><h3 id="上六-·-咸其辅颊舌" tabindex="-1">上六 · 咸其辅颊舌 <a class="header-anchor" href="#上六-·-咸其辅颊舌" aria-label="Permalink to &quot;上六 · 咸其辅颊舌&quot;">​</a></h3><ul><li>「辅、颊、舌」是面部与言语相关的部位，共同构成表达系统</li><li>感应走完全身后，终于找到出口，化为表情、语言、书写与行动</li><li>关键不是说多说少，是如实、合时、不夸张、不借表达操控</li></ul><blockquote><p>感受了，如实表达；不压抑，不表演，不夸大，也不伤人。</p></blockquote><h2 id="【原典层】字词释义" tabindex="-1">【原典层】字词释义 <a class="header-anchor" href="#【原典层】字词释义" aria-label="Permalink to &quot;【原典层】字词释义&quot;">​</a></h2>',21)),t(d,{title:"字词释义",items:[{term:"咸",pinyin:["xián"],meaning:"感。无心之感，不以私心强作感应。"},{term:"拇",pinyin:["mǔ"],meaning:"脚趾。感应最初的触动。"},{term:"腓",pinyin:["féi"],meaning:"小腿肚。被感带动，切忌抢先妄动。"},{term:"股",pinyin:["gǔ"],meaning:"大腿。主控感出现，执著于跟随。"},{term:"憧憧",pinyin:["chōng","chōng"],meaning:"往来不定、心念纷纭。"},{term:"脢",pinyin:["méi"],meaning:"背脊肉。内守、有根、有感而不被牵走。"},{term:"辅颊舌",pinyin:["fǔ","jiá","shé"],meaning:"面颊与口舌，表达系统。"},{term:"虚受人",pinyin:["xū","shòu","rén"],meaning:"心中留有空间，容纳他人的处境与存在。"},{term:"朋从尔思",pinyin:["péng","cóng","ěr","sī"],meaning:"心念所系，同类相从。"},{term:"取女吉",pinyin:["qǔ","nǚ","jí"],meaning:"男下女，刚者下就于柔者，故能感通。"}]}),i[2]||(i[2]=n('<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一卦在说什么" tabindex="-1">象：这一卦在说什么 <a class="header-anchor" href="#象-这一卦在说什么" aria-label="Permalink to &quot;象：这一卦在说什么&quot;">​</a></h3><p>咸卦讲的是<strong>感应</strong>。上兑（泽）下艮（山），泽在山上，山有凹处、泽得以停聚，山不动、泽能润泽——感应不是控制，是在适当的关系与空间中自然发生的相感。</p><p>卦辞「亨，利贞，取女吉」点明：感应通畅则亨，但需守正；刚者放低、靠近、容纳，才能真正感通。</p><h3 id="理-为什么这一卦重要" tabindex="-1">理：为什么这一卦重要 <a class="header-anchor" href="#理-为什么这一卦重要" aria-label="Permalink to &quot;理：为什么这一卦重要&quot;">​</a></h3><p><strong>感是入口，贞是边界</strong>。有感而不失正，才是咸的亨通。若没有「利贞」，感应很容易滑向情绪投射、欲望追逐、关系操控，用「本心」包装冲动。</p><p>咸不是没有心，是不以私心强作感应；不是没有念，是不执念为主。</p><h3 id="用-今天如何应用" tabindex="-1">用：今天如何应用 <a class="header-anchor" href="#用-今天如何应用" aria-label="Permalink to &quot;用：今天如何应用&quot;">​</a></h3><ol><li>感应来了先居住在感受里，不急着表态（六二居吉）</li><li>放下「我要靠此成为谁」的抓取（九三）</li><li>在念头纷乱中守正（九四贞吉悔亡）</li><li>内守，有感而不被感带走（九五）</li><li>如实表达，不压抑不表演不夸大（上六）</li></ol><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>六爻以身体部位写感应推进：</p><table tabindex="0"><thead><tr><th>爻位</th><th>原文</th><th>身体部位</th><th>生命理解</th></tr></thead><tbody><tr><td>初六</td><td>咸其拇</td><td>脚趾</td><td>最初触动，尚未被意念加工</td></tr><tr><td>六二</td><td>咸其腓，凶，居吉</td><td>小腿</td><td>被感带动，切忌抢先妄动</td></tr><tr><td>九三</td><td>咸其股，执其随，往吝</td><td>大腿</td><td>主控感出现，执著于跟随</td></tr><tr><td>九四</td><td>贞吉悔亡，憧憧往来，朋从尔思</td><td>心</td><td>念头纷至，守正可出乱入定</td></tr><tr><td>九五</td><td>咸其脢，无悔</td><td>脊背</td><td>内守、有根、有感而不被牵走</td></tr><tr><td>上六</td><td>咸其辅颊舌</td><td>辅颊舌</td><td>感应化为表达</td></tr></tbody></table><p>核心洞见：</p><ol><li><strong>咸 = 无心之感</strong>——不以私心强作感应</li><li><strong>感是入口，贞是边界</strong>——有感而不失正，才是亨通</li><li><strong>虚受人</strong>——山给泽空间，泽赋山生机</li><li><strong>损是清出空间，咸是让真实感应发生</strong>——先经过损，才懂得咸</li></ol><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><p>这次学习形成的不是一组知识点，而是一条生命线：</p><p>快要失去 → 本能抗拒 → 主动做减法 → 损之又损 → 留下根基 → 心中有空间 → 能虚受人 → 有感而不强作 → 有念而不尽随 → 有表达而能如实</p><p>三个认识：</p><ol><li><strong>变了，仍然是我</strong>——学易经前后、骨折前后、经历挫折之后，仍然是我。变化的是处境与理解，延续的是那个愿意承认经历、承担经历、继续前行的人。</li><li><strong>不把浑浊情绪施加给别人</strong>——不仅不把自己不愿承受的行为强加给别人，也不把自己未经处理的情绪、欲望、怨气施加给别人。</li><li><strong>向内能觉，向外能感</strong>——知道自己正被什么带走，知道什么正轻轻触动自己。见其可为，则自然去做；觉其失守，则自然回来。</li></ol><p><strong>一句话收整卦</strong>：损之又损，损出了根；有根之后，感而无心；无心之感，才是真咸。</p><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li>相关卦象：恒（第三十二卦）、损（第四十一卦）</li><li>咸与恒：咸讲感应如何发生，恒讲什么能长久——咸若只是一时感动仍会消散，只有每次念头纷起时都能回到根、回到当下，感应才不会变成执著</li><li>咸与损：同样是山泽，上下不同——咸上兑下艮（感应），损上艮下兑（减损）；先经过损，才懂得咸</li><li>相关专题：<a href="/Dao/topics/yin-yang">阴阳</a>、<a href="/Dao/topics/xiang-shu-li">象数理</a></li></ul>',22))])}}});export{x as __pageData,q as default};
